FUNCTION_BLOCK FB_S01
VAR_INPUT
    StartBtn : BOOL;
    LeftPartPresent : BOOL;
    RightPartPresent : BOOL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    ClampLeft : BOOL;
    ClampRight : BOOL;
    Busy : BOOL;
    Status : WORD;
END_VAR
VAR
    StartBtnLast : BOOL := FALSE;
    StartPulse : BOOL := FALSE;
    FirstScan : BOOL := TRUE;
    BothRequest : BOOL := FALSE;
END_VAR

(* S01 semantic note:
   Requirement 2 wording mixes "auto yield" and "later station waits".
   This implementation treats a rising edge as a request for the part-present side.
   If the other side is already clamped, it yields in the same scan before the
   requested side clamps. If both sides are part-present and neither is clamped,
   both are considered requested simultaneously and no clamp is made; Status is 16#8101.
*)

IF FirstScan THEN
    ClampLeft := FALSE;
    ClampRight := FALSE;
    Busy := FALSE;
    IF NOT EStop_NC THEN
        Status := 16#8102;
    ELSE
        Status := 16#0000;
    END_IF;
    StartBtnLast := StartBtn;
    FirstScan := FALSE;
ELSE
    StartPulse := StartBtn AND NOT StartBtnLast;

    IF NOT EStop_NC THEN
        (* K4 / C1: emergency stop has highest priority. *)
        ClampLeft := FALSE;
        ClampRight := FALSE;
        Busy := FALSE;
        Status := 16#8102;
    ELSE
        (* K2 / C2 / C2b: a clamp may not remain if the corresponding part is absent. *)
        IF NOT LeftPartPresent THEN
            ClampLeft := FALSE;
        END_IF;
        IF NOT RightPartPresent THEN
            ClampRight := FALSE;
        END_IF;

        (* K1 / C4: final interlock check before edge processing. *)
        IF ClampLeft AND ClampRight THEN
            ClampLeft := FALSE;
            ClampRight := FALSE;
            Status := 16#8101;
        ELSE
            Status := 16#0000;

            IF StartPulse THEN
                BothRequest := LeftPartPresent AND RightPartPresent
                               AND NOT ClampLeft AND NOT ClampRight;

                IF BothRequest THEN
                    (* Two sides requested at the same rising edge. *)
                    Status := 16#8101;
                ELSE
                    IF LeftPartPresent AND RightPartPresent THEN
                        (* Both parts present; one side already clamped, so the other side
                           yields/alternates to the requested other side. *)
                        IF ClampLeft AND NOT ClampRight THEN
                            ClampLeft := FALSE;
                            ClampRight := TRUE;
                        ELSIF ClampRight AND NOT ClampLeft THEN
                            ClampRight := FALSE;
                            ClampLeft := TRUE;
                        END_IF;
                    ELSIF LeftPartPresent AND NOT RightPartPresent THEN
                        (* Left requested; right must yield. *)
                        ClampRight := FALSE;
                        ClampLeft := TRUE;
                    ELSIF RightPartPresent AND NOT LeftPartPresent THEN
                        (* Right requested; left must yield. *)
                        ClampLeft := FALSE;
                        ClampRight := TRUE;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;

        (* Re-enforce part-present requirements after edge actions. *)
        IF NOT LeftPartPresent THEN
            ClampLeft := FALSE;
        END_IF;
        IF NOT RightPartPresent THEN
            ClampRight := FALSE;
        END_IF;

        (* K1 / C4: never allow both clamps true at end of scan. *)
        IF ClampLeft AND ClampRight THEN
            ClampLeft := FALSE;
            ClampRight := FALSE;
            Status := 16#8101;
        END_IF;

        (* Busy reflects that a station is currently clamped. *)
        Busy := ClampLeft OR ClampRight;
    END_IF;

    StartBtnLast := StartBtn;
END_IF;

END_FUNCTION_BLOCK
